type Signup struct {
	Email string   `validate:"required,email"`
	Age   int      `validate:"gte=18,lte=120"`
	Tags  []string `validate:"required,dive,min=2"` // dive: each tag min len 2
}

func main() {
	v := validator.New()
	s := Signup{Email: "nope", Age: 15, Tags: []string{"a"}}
	if err := v.Struct(s); err != nil {
		for _, fe := range err.(validator.ValidationErrors) {
			fmt.Printf("%s failed on %q\n", fe.Field(), fe.Tag())
		}
	}
	// Email failed on "email"
	// Age failed on "gte"
	// Tags[0] failed on "min"
}
